body:
@BYK Thanks for the fast reply. Can you elaborate on "case #2 being normal"? Thank you.

This is better sample for both cases:

.eslintrc

```
{
  "rules": {
    "indent": [2, 2],
    "quotes": [2, "single"],
    "linebreak-style": [2, "unix"],
    "semi": [2, "always"],
    "curly": [2, "multi-line"],
    "handle-callback-err": [2, "^err"],
    "valid-jsdoc": [2, {
      "requireReturn": false,
      "requireReturnDescription": false,
      "prefer": {
        "return": "returns"
      }
    }],
    "key-spacing": 0,
    "strict": 0,
    "no-underscore-dangle": 0,
    "no-use-before-define": 0,
    "dot-notation": 0,
    "eol-last": 0,
    "no-new": 0,
    "semi-spacing": 0,
    "no-multi-spaces": 0,
    "eqeqeq": 0,
    "no-mixed-requires": 0
  },
  "env": {
    "node": true,
    "browser": true
  }
}
```

buster.js

```
module.exports =
{
  'Unit tests':
  {
    rootPath: './',
    environment: 'node',
    tests:
    [
      'test/test-*.js'
    ],
    sources:
    [
      '*.js',
      'test/**.js'
    ]
  }
};
```

index.js

```
'use strict';

var path      = require('path')
  , crypto    = require('crypto')
    // thrid-party
  , glob      = require('glob')
  , requirejs = require('requirejs')
  ;

module.exports = function(grunt)
{
};
```

command I run:

```
eslint -c .eslintrc {*,test/*}.js
```

Thank you.

@alexindigo heh :) The following style is usually more helpful:

```
module.exports =
{
  'Unit tests':
  {
    rootPath: './',  // Expected indentation of 6 characters but found 4  (indent)
```
